import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.io.BufferedWriter;
import java.io.OutputStreamWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        int n = in.nextInt();
        out.print(solve(n));
        out.close();
    }

    static final int MOD = 1000000007;

    static int solve(int n) {
        int N = 2 * n;
        int[][] prev = new int[N + 1][2];
        int[][] cur = new int[N + 1][2];
        prev[0][0] = prev[0][1] = 0;

        for (int i = 1; i <= N; i++) {
            for (int j = 0; j <= i; j++) {
                int k1 = 0;
                if (i - j >= 2) {
                    k1 = add(k1, prev[j + 1][0]);
                }
                if (j > 0) {
                    k1 = add(k1, prev[j - 1][0]);
                }
                cur[j][1] = k1;

                int best = 0;
                int v = 0;
                if (i - j >= 2) {
                    v = add(v, prev[j + 1][0]);
                }
                if (j > 0) {
                    v = add(v, prev[j - 1][0]);
                }
                best = Math.max(best, v);

                v = 0;
                if (i - j >= 2) {
                    v = add(v, prev[j + 1][0]);
                }
                if (j > 0) {
                    v = add(v, prev[j - 1][1]);
                    v = add(v, 1);
                }
                best = Math.max(best, v);

                v = 0;
                if (i - j >= 2) {
                    v = add(v, prev[j + 1][1]);
                    v = add(v, 1);
                }
                if (j > 0) {
                    v = add(v, prev[j - 1][0]);
                }
                best = Math.max(best, v);

                cur[j][0] = best;
            }
            int[][] temp = prev;
            prev = cur;
            cur = temp;
        }
        return prev[0][0];
    }

    static int add(int a, int b) {
        int res = a + b;
        if (res >= MOD) {
            res -= MOD;
        }
        return res;
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
